# The screens reached from You: title bar, back, league pills, switches (v507)
import os, sys, json, re
exec(open('p27bt.py').read().rsplit("\nwith sync_playwright() as p:", 1)[0])
ST = "(() => { const s = document.getElementById('sh27'), h = document.getElementById('sht27'), b = document.getElementById('shb27'); return [location.hash, document.documentElement.dataset.page, !s.hidden, h.textContent, !b.hidden, b.getAttribute('href'), (document.querySelector('#tb27 a.on') || {}).dataset ? document.querySelector('#tb27 a.on').dataset.t27 : '']; })()"
with sync_playwright() as p:
    b = p.chromium.launch(); ctx = b.new_context(viewport={'width': 412, 'height': 915}, service_workers='block', color_scheme='dark', is_mobile=True, has_touch=True)
    ctx.add_init_script(eval(init) + PL + FLAG); pg = ctx.new_page(); pg.on('pageerror', lambda e: E.append(str(e)[:200])); pg.route('**/*', rt)
    pg.goto('http://localhost:8777/rivl/#home'); pg.wait_for_timeout(2500)
    pg.tap('#tb27 [data-t27="you"]'); pg.wait_for_timeout(1500); print('You', pg.evaluate(ST))
    pg.goto('http://localhost:8777/rivl/#settings/menu'); pg.wait_for_timeout(1500); print('Settings list', pg.evaluate(ST))
    pg.tap('#shb27'); pg.wait_for_timeout(1200); print(' back ->', pg.evaluate(ST))
    pg.evaluate("location.hash = '#teams'"); pg.wait_for_timeout(2000); print('Teams', pg.evaluate(ST), 'pills', pg.evaluate("[...document.querySelectorAll('#lgtabs .lgt')].map(x => x.textContent.trim() + (x.classList.contains('on') ? '*' : ''))"))
    pg.tap('#lgtabs .lgt >> nth=1'); pg.wait_for_timeout(1500); print(' tap WNBA ->', pg.evaluate("[location.hash, document.querySelector('#lgtabs .lgt.on').textContent.trim(), document.querySelectorAll('#tlist .row.prow').length]"))
    pg.tap('#lgtabs .lgt >> nth=0'); pg.wait_for_timeout(1500)
    n0 = pg.evaluate("document.querySelectorAll('#tlist .star.on').length"); pg.tap('#tlist .row.prow .star >> nth=0'); pg.wait_for_timeout(700); print(' star toggles', n0, '->', pg.evaluate("document.querySelectorAll('#tlist .star.on').length")); pg.tap('#tlist .row.prow .star >> nth=0'); pg.wait_for_timeout(500)
    pg.tap('#main .chips .chip >> text=Following'); pg.wait_for_timeout(700); print(' Following switch on', pg.evaluate("document.querySelector('#main .chips .chip.on').textContent"))
    pg.tap('#shb27'); pg.wait_for_timeout(1200); print(' back ->', pg.evaluate(ST))
    pg.evaluate("location.hash = '#players'"); pg.wait_for_timeout(2500); print('Players', pg.evaluate(ST))
    pg.evaluate("location.hash = '#record'"); pg.wait_for_timeout(2000); print('Record', pg.evaluate(ST), 'old top bar shown', pg.evaluate("getComputedStyle(document.querySelector('#main > .topbar')).display"))
    pg.evaluate("location.hash = '#scores'"); pg.wait_for_timeout(2000); print('Scores', pg.evaluate(ST), 'search shown', pg.evaluate("!document.querySelector('#sh27 .shs27').hidden"))
    pg.goto('http://localhost:8777/rivl/#settings/menu'); pg.wait_for_timeout(1500)
    pg.tap('.set380 .segc button[data-theme="light"]'); pg.wait_for_timeout(600); print('theme ->', pg.evaluate("document.documentElement.dataset.theme"), pg.evaluate("document.querySelector('.set380 .segc button.on').textContent"))
    pg.tap('.set380 .segc button[data-theme="system"]'); pg.wait_for_timeout(400)
    pg.goto('http://localhost:8777/rivl/#settings/home'); pg.wait_for_timeout(1500); a = pg.evaluate("document.querySelector('#main .row.sw').getAttribute('aria-checked')"); pg.tap('#main .row.sw >> nth=0'); pg.wait_for_timeout(500); print('home switch', a, '->', pg.evaluate("document.querySelector('#main .row.sw').getAttribute('aria-checked')")); pg.tap('#main .row.sw >> nth=0')
    pg.tap('#main > .topbar .ib'); pg.wait_for_timeout(1000); print(' back from Home settings ->', pg.evaluate(ST))
    # the old design is untouched
    pg.evaluate("localStorage.setItem('hw:v5:rv27','false')"); pg.goto('http://localhost:8777/rivl/#teams'); pg.reload(); pg.wait_for_timeout(2500); print('old design: bar hidden', pg.evaluate("document.getElementById('sh27').hidden"), 'class', pg.evaluate("document.documentElement.className"))
    b.close()
print('errs', E)
